class UserController {
  private repo: UserRepository;
  constructor() {
    this.repo = new UserRepository();
  }
  getUser(id: string) { return this.repo.findById(id); }
}

class PaymentService {
  private processor: PaymentProcessor;
  constructor() {
    this.processor = ServiceLocator.resolve('PaymentProcessor');
  }
  charge(amount: number) { return this.processor.charge(amount); }
}

// Version A
class OrderProcessorV1 {
  constructor(private payment: PaymentGateway) {}
  process(order: Order) { return this.payment.charge(order.total); }
}

// Version B
class OrderProcessorV2 {
  process(order: Order) {
    const payment = ServiceRegistry.get<PaymentGateway>('PaymentGateway');
    return payment.charge(order.total);
  }
}
